INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Adressraum von IPv6 wirklich 2^128?', 2, '[{"text": "Ja", "correct": true, "because": "128 Bits definieren den Raum"}, {"text": "Nein", "correct": false, "because": "Standard ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Adressen bietet 2^32 im Vergleich zu 2^128?', 3, '[{"text": "Deutlich weniger", "correct": true, "because": "4,3 Milliarden vs. 3,4×10^38"}, {"text": "Etwa gleich", "correct": false, "because": "Exponentieller Unterschied"}, {"text": "Mehr", "correct": false, "because": "Falsche Richtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil hat 2^128 gegenüber 2^32?', 4, '[{"text": "Größerer Adresspool", "correct": true, "because": "Praktisch unerschöpflich"}, {"text": "Schnellere Routing", "correct": false, "because": "Nicht direkt verbunden"}, {"text": "Kleinere Adressen", "correct": false, "because": "Länger als IPv4"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2^32 ist IPv4. b) 2^128 ist IPv6.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "32 Bits für IPv4, 128 für IPv6"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide sind richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Vergleich von 2^128 und 2^32?', 5, '[{"text": "Protokollgeschwindigkeit", "correct": true, "because": "Adressraum-unabhängig"}, {"text": "Bitanzahl", "correct": false, "because": "Kern des Vergleichs"}, {"text": "Adressanzahl", "correct": false, "because": "Hauptunterschied"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2^32 für moderne Netze ausreicht?', 2, '[{"text": "Nein", "correct": true, "because": "Zu wenig Adressen"}, {"text": "Ja", "correct": false, "because": "IPv4 ist begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Größenordnung hat 2^128?', 3, '[{"text": "10^38", "correct": true, "because": "Ungefähr 3,4×10^38"}, {"text": "10^32", "correct": false, "because": "Zu klein"}, {"text": "10^64", "correct": false, "because": "Überschätzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften unterscheiden 2^128 von 2^32?', 5, '[{"text": "Enormer Adressraum", "correct": true, "because": "IPv6 ist riesig"}, {"text": "128-Bit-Struktur", "correct": true, "because": "IPv6 vs. 32-Bit IPv4"}, {"text": "Kleinere Subnetze", "correct": false, "because": "IPv6 hat größere"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) 2^32 ist etwa 4 Milliarden. b) 2^128 ist unendlich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist groß, aber endlich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für den Adressraum-Vergleich?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert 2^n"}, {"text": "Adresskapazität", "correct": false, "because": "Kern des Vergleichs"}, {"text": "Übertragungsrate", "correct": true, "because": "Unabhängig vom Raum"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 2^32 für IPv6 relevant?', 2, '[{"text": "Nein", "correct": true, "because": "IPv6 nutzt 2^128"}, {"text": "Ja", "correct": false, "because": "Nur IPv4"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede gibt es zwischen 2^128 und 2^32?', 4, '[{"text": "Adressanzahl", "correct": true, "because": "Exponenzieller Sprung"}, {"text": "Bitlänge", "correct": true, "because": "128 vs. 32"}, {"text": "Routing-Geschwindigkeit", "correct": false, "because": "Nicht direkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 2^128 alle Geräte der Welt abdeckt. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Praktisch unerschöpflich"}, {"text": "Nein", "correct": false, "because": "Übertrifft Bedarf bei Weitem"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich beim Vergleich von 2^128 und 2^32?', 3, '[{"text": "Kapazität", "correct": true, "because": "Hauptunterschied"}, {"text": "Darstellungsform", "correct": false, "because": "Sekundär"}, {"text": "Bandbreite", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2^32 ist begrenzt. b) 2^128 ist für IPv4.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, IPv6"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist ungenau"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet 2^128?', 5, '[{"text": "Unerschöpflicher Pool", "correct": true, "because": "3,4×10^38 Adressen"}, {"text": "Zukunftssicherheit", "correct": true, "because": "Für alle Geräte"}, {"text": "Kleinere Adressen", "correct": false, "because": "Länger als IPv4"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist beim Adressraum unwichtig?', 3, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert Größe"}, {"text": "Kapazität", "correct": false, "because": "Kernmerkmal"}, {"text": "Farbcodierung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist 2^32 für IoT ausreichend?', 2, '[{"text": "Nein", "correct": true, "because": "Zu wenig für Milliarden Geräte"}, {"text": "Ja", "correct": false, "because": "IPv4 ist limitiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2^128 praktisch unendlich ist?', 3, '[{"text": "Ja", "correct": true, "because": "Übersteigt jeden Bedarf"}, {"text": "Nein", "correct": false, "because": "Technisch endlich, aber riesig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bitlänge wähle ich für einen größeren Adressraum?', 4, '[{"text": "128", "correct": true, "because": "IPv6 mit 2^128"}, {"text": "32", "correct": false, "because": "IPv4 ist kleiner"}, {"text": "64", "correct": false, "because": "Kein Standard"}]');
